# frozen_string_literal: true

require "fileutils"

module Administratum
  # Host Tailwind mode: generates a CSS file with absolute paths into the
  # installed gem, so an app's Tailwind v4 build can include Administratum's
  # tokens, components and class sources. Import it after "tailwindcss" and
  # override any --color-adm-* token in your own @theme.
  module Tailwind
    module_function

    def root
      File.expand_path("../..", __dir__)
    end

    def contents
      <<~CSS
        /* Generated by bin/rails administratum:tailwind:sync. Do not edit; do not commit. */
        @import "#{root}/app/assets/tailwind/administratum/theme.css";
        @import "#{root}/app/assets/tailwind/administratum/components.css";
        @source "#{root}/app/views";
        @source "#{root}/app/helpers";
        @source "#{root}/app/assets/javascripts";
      CSS
    end

    def write(path)
      FileUtils.mkdir_p(File.dirname(path))
      File.write(path, contents)
      path
    end
  end
end
